        TEST_ASSERT(st == micant::NtStatus::Success, "NtQueryInformationProcess(ProcessDebugPort) succeeds");
        TEST_ASSERT(debugPort == 0, "ProcessDebugPort is 0 (No debugger present / Anti-cheat approved)");
