        TEST_ASSERT(ldr.getExport("api-ms-win-core-realtime-l1-1-1.dll", "QueryPerformanceFrequency") != nullptr, "api-ms realtime l1-1-1 exports QueryPerformanceFrequency");

        // api-ms-win-core-profile-l1-1-0.dll exports
