        // 2. Test CreateWorkGraphProgramRecord7 and GetWorkGraphCooperativeMatrixSupport2
        void* pRec7 = nullptr;
        hr = pDev23->CreateWorkGraphProgramRecord7(nullptr, 0x7, 33554432ULL, 512u, 0x01, 0x02, IID_ID3D12Device23, &pRec7);
