        TEST_ASSERT(rtlQos.HighPriorityBandwidthDeliveredGBps == 1536ULL, "RtlQuerySystemCpuFabricQosTelemetry reports 1536 GB/s");

        SYSTEM_CPU_FABRIC_QOS_TELEMETRY_INFORMATION win32Qos{};
