        // 1. Class 265: PagefileTierWearLevelingTelemetry
        SYSTEM_PAGEFILE_TIER_WEAR_LEVELING_TELEMETRY_INFORMATION wearInfo{};
        NtStatus status = RtlQuerySystemPagefileTierWearLevelingTelemetry(&wearInfo);
