        TEST_ASSERT(sparseAccel == 1, "Sparse acceleration supported");
        TEST_ASSERT(asyncAccum == 1, "Async accumulation supported");
        TEST_ASSERT(maxTileStages == 65536, "Max tile pipelining stages is 65536");
