        status = NtQuerySystemInformation_Export(302, &phaseInfo, sizeof(phaseInfo) - 1, &retLen);
        TEST_ASSERT(status == NtStatus::InfoLengthMismatch, "Class 302 buffer too small returns InfoLengthMismatch");
