        TEST_ASSERT(hr == 0, "CheckFeatureSupport for D3D12_FEATURE_D3D12_OPTIONS69 succeeds");
        TEST_ASSERT(opt69.WorkGraphsTier == 52u, "D3D12_OPTIONS69 reports WorkGraphsTier 52");
